def fires(b):
    # opponent has an immediate (playable) winning cell that I must block
    return len(b.their_playable_wins) > 0


def level(b):
    if not fires(b):
        return 0
    cols = set(c for (r, c) in b.their_playable_wins)
    if 1 in cols or 6 in cols:
        return 8
    return 5

def vertical_block(b):
    # columns where the opponent has three stacked on top with the cell above empty (a vertical must-block)
    out = []
    for c in range(7):
        h = b.heights[c]
        if 3 <= h <= 5 and all(b.grid[h - 1 - k][c] == 2 for k in range(3)):
            out.append(c)
    return out


def pat_a(b):
    return any(c in (0, 1, 5, 6) for c in vertical_block(b))


def pat_b(b):
    return (1, 1) in b.their_playable_wins


def pat_c(b):
    return b.grid[0][2] == 1 and b.grid[1][2] == 2 and b.heights[2] == 2 and b.heights[3] == 0


def fires(b):
    return pat_a(b) or pat_b(b) or pat_c(b)


def level(b):
    s = 0
    if pat_a(b):
        s += 5
    if pat_b(b):
        s += 6
    if pat_c(b):
        s += 6
    return min(9, s)

def block_on_last(b):
    # the cell I must block is directly on top of the opponent's last stone
    if b.last_col is None:
        return False
    return (b.last_row + 1, b.last_col) in b.their_playable_wins


def cap2(b):
    # my stone at the bottom of column 2 capped by theirs, nothing above
    return b.grid[0][2] == 1 and b.grid[1][2] == 2 and b.heights[2] == 2


def fires(b):
    return block_on_last(b) or cap2(b)


def level(b):
    s = 0
    if block_on_last(b):
        s += 6
    if cap2(b):
        s += 5
        if b.heights[3] == 0:
            s += 2
    return min(9, s)

def vertical_block(b, c):
    h = b.heights[c]
    return 3 <= h <= 5 and all(b.grid[h - 1 - k][c] == 2 for k in range(3))


def col1_block(b):
    # I must block the opponent in column 1 (any line)
    return any(c == 1 for (r, c) in b.their_playable_wins)


def col6_vertical(b):
    return vertical_block(b, 6)


def cap2(b):
    return b.grid[0][2] == 1 and b.grid[1][2] == 2 and b.heights[2] == 2 and b.heights[3] == 0


def fires(b):
    return col1_block(b) or col6_vertical(b) or cap2(b)


def level(b):
    s = 0
    if col1_block(b):
        s += 6
        if (1, 1) in b.their_playable_wins:
            s += 2
    if col6_vertical(b):
        s += 5
    if cap2(b):
        s += 5
    return min(9, s)

def vertical_block(b, c):
    h = b.heights[c]
    return 3 <= h <= 5 and all(b.grid[h - 1 - k][c] == 2 for k in range(3))


def left_block(b):
    # I must block the opponent in column 1 or 2 (any line)
    return any(c in (1,) for (r, c) in b.their_playable_wins)


def under_own_threat(b):
    # opponent's last stone sits directly under a cell that completes their (non-vertical) line
    if b.last_col is None:
        return False
    cell = (b.last_row + 1, b.last_col)
    return cell in b.their_playable_wins and not vertical_block(b, b.last_col)


def edge_vertical(b):
    return vertical_block(b, 6) or vertical_block(b, 0) or vertical_block(b, 5)


def cap2(b):
    return b.grid[0][2] == 1 and b.grid[1][2] == 2 and b.heights[2] == 2


def fires(b):
    return left_block(b) or edge_vertical(b) or (cap2(b) and b.heights[3] == 0)


def level(b):
    s = 0
    if left_block(b):
        s += 5
        if under_own_threat(b):
            s += 3
    if edge_vertical(b):
        s += 4
    if cap2(b):
        s += 3
        if b.heights[3] == 0:
            s += 2
    return min(9, s)
